import { countries, flagEmoji } from './country-index'

/**
 * Resolves Jellyfin production country names to country outlines.
 *
 * Modern borders come from a simplified Natural Earth 110m dataset
 * (`static/geo/countries.geojson`, public domain). Countries that no longer
 * exist come from a compact extract of historical-basemaps
 * (`static/geo/historical.json`, GPL-3.0) generated by
 * `.dovenv/scripts/build-geo-data.mjs`.
 */
export type CountryGeometry =
  | { type: 'Polygon'; coordinates: number[][][] }
  | { type: 'MultiPolygon'; coordinates: number[][][][] }

export interface CountryShape {
  /** Country name as it appears in the dataset. */
  name: string
  /** Whether the shape is an approximation of a historical border. */
  historical: boolean
  /** GeoJSON geometry, when a polygon is available. */
  geometry: CountryGeometry | null
  /** Leaflet-friendly point (`[lat, lng]`) used for the marker. */
  label: [number, number]
}

interface CountryFeatureProperties {
  NAME?: string | null
  NAME_EN?: string | null
  NAME_ES?: string | null
  ISO_A3?: string | null
  ISO_A2?: string | null
  ADM0_A3?: string | null
  LABEL_X?: number | null
  LABEL_Y?: number | null
}

interface CountryFeature {
  type: 'Feature'
  properties: CountryFeatureProperties
  geometry: CountryGeometry
}

interface HistoricalEpoch {
  year: number
  /** [lng, lat] */
  label: [number, number]
  geometry: CountryGeometry
}

interface HistoricalEntity {
  name: string
  aliases: string[]
  /** Optional representative point `[lng, lat]` (e.g. a capital). */
  label?: [number, number]
  epochs: HistoricalEpoch[]
}

interface GeoData {
  featureByIso: Map<string, CountryFeature>
  featureByName: Map<string, CountryFeature>
  isoByAlias: Map<string, string>
  historicalByAlias: Map<string, HistoricalEntity>
}

let geoDataPromise: Promise<GeoData> | null = null

function normalize(value: string): string {
  return value
    .toLowerCase()
    .normalize('NFD')
    .replace(/[\u0300-\u036f]/g, '')
    .replace(/[^a-z0-9]+/g, ' ')
    .trim()
}

const ISO_ALIASES_EXTRA: Record<string, string> = {
  usa: 'USA',
  us: 'USA',
  'united states of america': 'USA',
  uk: 'GBR',
  'great britain': 'GBR',
  britain: 'GBR',
  uae: 'ARE',
  'south korea': 'KOR',
  'north korea': 'PRK',
  russia: 'RUS',
  czechia: 'CZE',
  'czech republic': 'CZE',
  'ivory coast': 'CIV',
  'cape verde': 'CPV',
  'east timor': 'TLS',
  burma: 'MMR',
  swaziland: 'SWZ',
  macedonia: 'MKD',
  'the netherlands': 'NLD',
  holland: 'NLD',
  'republic of ireland': 'IRL',
}

function buildIsoAliases(): Map<string, string> {
  const index = new Map<string, string>()

  for (const country of countries) {
    const iso3 = country.c3
    if (!iso3) continue

    const add = (value: string | null | undefined) => {
      if (!value) return
      const key = normalize(value)
      if (key && !index.has(key)) index.set(key, iso3)
    }

    add(country.c2)
    add(country.c3)
    add(country.ci)
    add(country.n)
    add(country.o)

    for (const native of country.nn ?? []) add(native)
    for (const demonym of country.d ?? []) add(demonym)
  }

  const extra: Record<string, string> = ISO_ALIASES_EXTRA
  for (const [alias, iso3] of Object.entries(extra)) {
    if (!index.has(alias)) index.set(alias, iso3)
  }

  return index
}

let flagIndex: Map<string, string> | null = null

function buildFlagIndex(): Map<string, string> {
  const index = new Map<string, string>()
  const flagByIso3 = new Map<string, string>()

  const add = (value: string | null | undefined, flag: string | undefined) => {
    if (!value || !flag) return
    const key = normalize(value)
    if (key && !index.has(key)) index.set(key, flag)
  }

  for (const country of countries) {
    const flag = flagEmoji(country.c2)
    if (!flag) continue
    if (country.c3) flagByIso3.set(country.c3, flag)

    add(country.c2, flag)
    add(country.c3, flag)
    add(country.ci, flag)
    add(country.n, flag)
    add(country.o, flag)

    for (const native of country.nn ?? []) add(native, flag)
  }

  for (const [alias, iso3] of Object.entries(ISO_ALIASES_EXTRA)) {
    add(alias, flagByIso3.get(iso3))
  }

  return index
}

/** Flag emoji for a Jellyfin production-country name, when it exists. */
export function countryFlagEmoji(name: string): string | undefined {
  flagIndex ??= buildFlagIndex()
  return flagIndex.get(normalize(name))
}

/**
 * Resolves the country contained in a free-form place string, such as a
 * person's birthplace ("Chicago, Illinois, USA"). Segments are tried from the
 * end, which is where Wikidata/Jellyfin put the country.
 */
export async function resolveCountryName(place: string): Promise<string | null> {
  const raw = place?.trim()
  if (!raw) return null

  const segments = raw
    .split(',')
    .map((part) => part.trim())
    .filter(Boolean)

  try {
    const data = await loadGeoData()
    for (let index = segments.length - 1; index >= 0; index -= 1) {
      const segment = segments[index]!
      const key = normalize(segment)
      if (!key) continue

      const iso3 = data.isoByAlias.get(key)
      const feature = iso3 ? data.featureByIso.get(iso3) : data.featureByName.get(key)
      if (feature) return feature.properties.NAME ?? segment

      const historical = data.historicalByAlias.get(key)
      if (historical) return historical.name
    }
  } catch {
    // Offline: the caller keeps rendering the place as a plain label.
  }

  return null
}

async function fetchJson<T>(url: string): Promise<T> {
  const res = await fetch(url)
  if (!res.ok) throw new Error(`Could not load ${url} (${res.status})`)
  return res.json() as Promise<T>
}

async function loadGeoData(): Promise<GeoData> {
  if (!geoDataPromise) {
    geoDataPromise = (async () => {
      const [countries, historical] = await Promise.all([
        fetchJson<{ features: CountryFeature[] }>('/geo/countries.geojson'),
        fetchJson<Record<string, HistoricalEntity>>('/geo/historical.json'),
      ])

      const featureByIso = new Map<string, CountryFeature>()
      const featureByName = new Map<string, CountryFeature>()

      for (const feature of countries.features) {
        const props = feature.properties
        if (props.ISO_A3) featureByIso.set(props.ISO_A3, feature)
        if (props.ADM0_A3) featureByIso.set(props.ADM0_A3, feature)

        const names = [props.NAME, props.NAME_EN, props.NAME_ES]
        for (const name of names) {
          if (!name) continue
          const key = normalize(name)
          if (key && !featureByName.has(key)) featureByName.set(key, feature)
        }
      }

      const historicalByAlias = new Map<string, HistoricalEntity>()
      for (const entity of Object.values(historical)) {
        for (const alias of entity.aliases) {
          historicalByAlias.set(normalize(alias), entity)
        }
      }

      return { featureByIso, featureByName, isoByAlias: buildIsoAliases(), historicalByAlias }
    })()
  }
  return geoDataPromise
}

function pickEpoch(entity: HistoricalEntity, year?: number): HistoricalEpoch {
  if (!year || !Number.isFinite(year)) return entity.epochs[entity.epochs.length - 1]!
  let best = entity.epochs[0]!
  let bestDistance = Math.abs(best.year - year)
  for (const epoch of entity.epochs) {
    const distance = Math.abs(epoch.year - year)
    if (distance < bestDistance) {
      best = epoch
      bestDistance = distance
    }
  }
  return best
}

function featureLabel(feature: CountryFeature): [number, number] {
  const { LABEL_Y, LABEL_X } = feature.properties
  if (typeof LABEL_Y === 'number' && typeof LABEL_X === 'number') return [LABEL_Y, LABEL_X]

  // Fall back to a rough bbox center; only used for marker placement.
  const coords: number[][] = []
  const collect = (value: unknown) => {
    if (!Array.isArray(value)) return
    if (typeof value[0] === 'number' && typeof value[1] === 'number') {
      coords.push(value as number[])
      return
    }
    for (const child of value) collect(child)
  }
  collect(feature.geometry)
  if (!coords.length) return [0, 0]
  let minLat = Infinity
  let maxLat = -Infinity
  let minLng = Infinity
  let maxLng = -Infinity
  for (const [lng, lat] of coords) {
    minLat = Math.min(minLat, lat!)
    maxLat = Math.max(maxLat, lat!)
    minLng = Math.min(minLng, lng!)
    maxLng = Math.max(maxLng, lng!)
  }
  return [(minLat + maxLat) / 2, (minLng + maxLng) / 2]
}

/**
 * Resolves a production country (as returned by Jellyfin) to a shape.
 *
 * Historical names (USSR, Yugoslavia, Czechoslovakia, …) are matched first and
 * use the border closest to `year` when it is available. Unknown names return
 * `null` so the caller can decide whether to skip them.
 */
export async function resolveCountryShape(
  name: string,
  year?: number
): Promise<CountryShape | null> {
  const raw = name?.trim()
  if (!raw) return null
  const key = normalize(raw)

  try {
    const data = await loadGeoData()

    const historical = data.historicalByAlias.get(key)
    if (historical) {
      const epoch = pickEpoch(historical, year)
      const point = historical.label ?? epoch.label
      return {
        name: historical.name,
        historical: true,
        geometry: epoch.geometry,
        label: [point[1], point[0]],
      }
    }

    const iso3 = data.isoByAlias.get(key)
    const feature = (iso3 ? data.featureByIso.get(iso3) : undefined) ?? data.featureByName.get(key)
    if (feature) {
      return {
        name: feature.properties.NAME ?? raw,
        historical: false,
        geometry: feature.geometry,
        label: featureLabel(feature),
      }
    }
  } catch {
    // Static geodata can fail to load (offline); fall back to point markers.
  }

  return null
}

/** Name used on the map popup: keep the historical label Jellyfin gave us. */
export function displayCountryName(name: string): string {
  return name.trim()
}
